"""Build the public shops from the existing creator identity and site components."""
from pathlib import Path
import runpy,html,re

ROOT=Path(__file__).resolve().parents[1]
base=runpy.run_path(str(ROOT/'scripts/generate-creator-pages.py'))
head,settings,dialog,footer=map(base.get,['head','settings','dialog','footer'])
V=(ROOT/'VERSION').read_text().strip()
PRODUCTS=[
 dict(slug='june.rowan',key='june',name='June Rowan',asset='june-rowan',sku='easier-week',title='The Easier<br>Week Kit',plain='The Easier Week Kit',price=0,tag='Small plans. Room for real life.',intro='A printable workbook and an editable planner for walks, familiar meals, evening cues and easy restarts.',files=['8-page US Letter workbook','Editable offline weekly planner','Print, export and import your plans'],benefits=[('Map a flexible week','Choose one useful priority, leave room for changes and keep daily notes in one place.'),('Make ordinary things easier','Plan one familiar meal, check the kitchen and bring a grocery list you can use.'),('Pick up from today','A restart page and weekly review help you keep what worked and change what added effort.')],preview='june-preview.png',caption='A real page from the workbook: a weekly map with space for your own plans.',art='<div class="paper"><p class="paper-label">MY EASIER WEEK</p><h3>One useful plan.<br>Room to move.</h3><div class="week-grid">'+''.join('<div><b>'+d+'</b><span></span><span></span></div>' for d in ['MON','TUE','WED','THU','FRI','SAT','SUN'])+'</div><p class="paper-foot">Week of ________ &nbsp; My small priority ________</p></div>',sample='<label class="sample-label">One small priority for your week<input placeholder="For example: step outside at lunch" maxlength="140"></label><p class="sample-note">Try a small starting point. The full planner adds daily notes, meal planning, cues and backup exports.</p>'),
 dict(slug='nora.vela',key='nora',name='Nora Vela',asset='nora-vela',sku='before-you-spend',title='Before<br>You Spend',plain='Before You Spend Kit',price=0,tag='Put the price in context.',intro='Compare recurring costs, setup effort and break-even sales with a spreadsheet, browser calculator and worked guide.',files=['Editable Excel workbook: two worksheets','Offline cost and break-even calculator','4-page worked-example guide'],benefits=[('Compare the same period','Put one-time, monthly and annual charges on a shared timeline.'),('Keep time visible','Show setup hours separately, with an optional value you choose for your time.'),('See what a sale contributes','Account for variable costs and fee assumptions before calculating break-even sales.')],preview='nora-preview.png',caption='The actual workbook, with blue editable inputs and separate cash and time costs. Starting numbers are hypothetical.',art='<div class="paper"><p class="paper-label">BEFORE YOU SPEND</p><h3>Same price tag.<br>A different calendar.</h3><div class="cost-row"><span>Monthly example</span><b>$15</b></div><div class="cost-row"><span>Twelve payments</span><b>$180</b></div><div class="cost-row"><span>Setup effort</span><b>Count it too.</b></div><p class="paper-foot">Hypothetical example · USD · Your inputs, your comparison.</p></div>',sample='<label class="sample-label">Monthly price ($)<input id="sample-price" type="number" min="0" max="100000" step="0.01" value="15"></label><p class="sample-result">Twelve payments: <strong id="sample-total">$180.00</strong></p><p class="sample-note">The full calculator adds one-time and annual costs, setup effort, fees and break-even sales.</p>'),
 dict(slug='elena.brooks',key='elena',name='Elena Brooks',asset='elena-brooks',sku='say-it-clearly',title='Say It<br>Clearly',plain='Say It Clearly',price=0,tag='Find the words. Make them yours.',intro='48 editable messages for invitations, clear requests, warm declines, changed plans, apologies and everyday check-ins.',files=['Searchable, editable offline message library','10-page printable message book','48 original messages across eight situations'],benefits=[('Start with the situation','Find a useful starting point instead of staring at a blank message.'),('Keep the detail that helps','Add a day, a time or a specific request so the other person has something to answer.'),('Make it sound like you','Edit the words, copy the message and send it yourself when you are ready.')],preview='elena-preview.png',caption='A real page from the message book. The full library lets you search, edit and copy all 48 messages.',art='<div class="paper"><p class="paper-label">SAY IT CLEARLY</p><h3>A request they<br>can answer.</h3><div class="message-bubble">Can you let me know by Thursday? I need to confirm the reservation.</div><p class="paper-foot">48 starting points · Eight everyday situations</p></div>',sample='<label class="sample-label">Try editing this invitation<textarea id="sample-message">Want to get coffee Saturday around 11? If that does not work, what day is better?</textarea></label><button class="sample-copy" type="button">Copy this sample</button><p class="sample-note" id="sample-status" role="status">The full library includes 48 messages you can search and adapt.</p>'),
]

for p in PRODUCTS:
    esc=html.escape
    original=(ROOT/(p['slug']+'.html')).read_text()
    video=re.search(r'<section class="wrap video-section".*?</section>',original).group(0)
    handle=next(h['handle'] for h in base['HOSTS'] if h['slug']==p['slug'])
    files=''.join('<li>'+esc(x)+'</li>' for x in p['files'])
    benefits=''.join('<article class="note"><span class="number">0'+str(i)+'</span><h3>'+esc(t)+'</h3><p>'+esc(c)+'</p></article>' for i,(t,c) in enumerate(p['benefits'],1))
    body=f'''<body data-host="{p['key']}"><header class="wrap bar"><a class="brand" href="{p['slug']}">{p['name']}</a><nav aria-label="Primary"><a href="#preview">Preview</a><a href="#shop">Shop</a>{settings()}</nav></header><main><section class="wrap hero shop-hero"><div class="hero-copy"><p class="eyebrow">Digital tools for everyday life</p><h1>{p['title']}</h1><p class="intro">{p['intro']}</p><p class="hero-price">${p['price']} <span>USD · free introductory offer</span></p><div class="actions"><a class="button" href="#shop">Get the free kit <span aria-hidden="true">↓</span></a><a class="text-link" href="#preview">Try a free preview</a></div><div class="host-stamp"><img src="assets/creators/{p['asset']}-profile.jpg" width="48" height="48" alt="AI-generated portrait of {p['name']}"><span><b>{p['name']}</b><small>Fictional AI creator · Published by Web By Elie</small></span></div></div><div class="product-art" aria-label="Product preview">{p['art']}<span class="format-label">FREE INTRODUCTORY DOWNLOAD · NO CARD REQUIRED</span></div></section><section class="wrap" aria-label="How the kit helps"><div class="section-line"><span>{p['tag']}</span><span>Kit 01</span></div><div class="notes">{benefits}</div></section><section class="wrap preview-section" id="preview"><div><p class="eyebrow">Take a look inside</p><h2>A small preview.<br>A useful starting point.</h2>{p['sample']}<p class="preview-caption">{p['caption']} <a href="assets/shop/{p['preview']}" target="_blank" rel="noopener">Enlarge the page ↗</a></p></div><a class="preview-page" href="assets/shop/{p['preview']}" target="_blank" rel="noopener" aria-label="Enlarge actual product page"><img src="assets/shop/{p['preview']}" alt="Actual preview page from {p['plain']}" loading="lazy"></a></section><section class="wrap purchase-section" id="shop"><div><p class="eyebrow">Yours to keep</p><h2>{p['plain']}</h2><ul class="included">{files}</ul><p class="purchase-detail">A ZIP download for your computer or phone. Extract the files, open the PDF or HTML tool, and get started. The HTML tools work offline in a current browser. Personal or internal household/business use; no resale.</p><p class="purchase-detail">Complete the free checkout to get your download immediately and by email. Your download link stays available for 30 days. Keep the files for continued use. Need a hand? <a href="mailto:hello@web-by-elie.com">hello@web-by-elie.com</a>.</p></div><form class="buy-card" data-sku="{p['sku']}"><p class="buy-price">${p['price']}<span>USD</span></p><p>Free introductory offer. No card required.<br>No subscription or future charge.</p><label class="sample-label">Email address <input type="email" name="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"></label><label class="consent"><input type="checkbox" name="letter"><span>Yes, email me Web By Elie’s letter with new tips, tools and offers from June, Nora and Elena. Optional; unsubscribe anytime.</span></label><label class="consent"><input type="checkbox" name="terms" required><span>I agree to the <a href="creators.terms" target="_blank" rel="noopener">digital product terms</a> and have read the <a href="creators.privacy" target="_blank" rel="noopener">privacy policy</a>.</span></label><label class="consent"><input type="checkbox" name="digital" required><span>I would like immediate access to the digital files.</span></label><button class="button checkout" type="submit">Get the free kit — Stripe checkout</button><p class="checkout-status" role="status" aria-live="polite"></p><small>Stripe handles this $0 order. An email address is required to deliver your kit. Letters are optional; no card is required.</small></form></section>{video}<section class="wrap shop-faq"><h2>A few useful details.</h2><details><summary>Will this work on my phone?</summary><p>Yes. PDFs open in a PDF viewer, and HTML tools open in a current browser after extracting the ZIP. On some phones, opening local HTML files is easier on a computer. Nora’s Excel workbook requires an application that opens .xlsx files.</p></details><details><summary>Will I be charged later?</summary><p>No. This introductory download costs $0. Claiming it does not create a subscription, automatic renewal or future charge.</p></details><details><summary>What if I need help?</summary><p>Email hello@web-by-elie.com with your order email and reference for download help or product questions. Never send passwords or card details.</p></details><details><summary>Who makes and sells this?</summary><p>Web By Elie publishes the kit and offers it free during the introductory period. {p['name']} is a fictional AI presenter, with an AI-generated image and voice. The product does not represent a real presenter’s personal experience or professional qualifications.</p></details></section></main>{footer(p['name'])}<p class="wrap social-follow"><a href="https://www.instagram.com/{handle}/">Follow {p['name']} on Instagram ↗</a></p><div class="sticky"><a class="button" href="#shop">{p['plain']} · ${p['price']}</a></div>{dialog()}<script src="assets/creator-shop.js?v={V}" defer></script></body></html>'''
    metadata=head(p['plain']+' | '+p['name'],p['intro'],p['slug'],p['asset']+'-profile.jpg').replace('</head>',f'<link rel="stylesheet" href="assets/creator-shop.css?v={V}"></head>')
    (ROOT/(p['slug']+'.html')).write_text(metadata+body)

policies={
 'privacy':('Privacy Policy','''<h2>Who operates the shops</h2><p>Web By Elie operates the June Rowan, Nora Vela and Elena Brooks digital product shops. These are fictional AI presenters. Contact hello@web-by-elie.com.</p><h2>Purchases and delivery</h2><p>Stripe processes orders through the existing Photos By Elie merchant account used by Web By Elie. During this $0 introductory offer, Stripe collects your email and order information for fulfillment without collecting a payment method. For any earlier paid orders, Stripe handles payment details. These pages do not store card details. Stripe’s own privacy policy applies to its processing.</p><p>Cloudflare stores product files and order references used for delivery. Delivery records contain the purchased product, Stripe session reference, status and access expiry. A private link grants access for 30 days; do not share it. Resend processes your purchase email and delivery message so we can send the link. Delivery records expire after 30 days. Stripe and email providers may retain their own records under their policies; we do not promise their deletion on that date.</p><h2>Your offline tools</h2><p>Downloaded tools work locally. June’s planner saves notes in your browser when available; exported backups remain on your device. Elena’s edits are temporary. These tools do not send your entries to Web By Elie or external services.</p><h2>Site preferences</h2><p>Display preferences are stored locally. The delivery page temporarily remembers its private order reference in session storage. You may separately opt in to Web By Elie’s letter about tips, tools and offers from these creators. The box is optional and unchecked. Completed opt-ins are stored privately with the email address, source and dated consent until you unsubscribe or request deletion. Each letter includes an unsubscribe link; you can also email hello@web-by-elie.com. Downloading a kit without opting in does not subscribe you. No advertising tracker is added by these shops. Cloudflare and Stripe may process technical information for hosting, security and payment operations.</p><h2>Your choices</h2><p>Contact hello@web-by-elie.com for access, correction or deletion requests. Include the purchase email and receipt reference, never card details. Required financial records may need to be retained. Manage device-local planner notes, backups and preferences on your own device.</p>'''),
 'terms':('Digital Product Terms','''<h2>Seller and products</h2><p>Web By Elie sells the digital kits described on each shop page. Stripe checkout uses the existing Photos By Elie payment account; your bank statement may show Photos By Elie. Contact hello@web-by-elie.com.</p><h2>Price and payment</h2><p>Prices are in US dollars. All three kits currently have an introductory price of $0. No card, coupon, subscription or automatic renewal is required. Completing a free order does not create a future charge. No offer end date is announced; any later price change applies only to new orders.</p><h2>Delivery and access</h2><p>After completing checkout, you can download a ZIP from the delivery page and receive a private recovery link by email. Download access lasts 30 days after the order. Save the files for continued use. Earlier paid orders remain accessible under their original terms. Contact us if your email or download does not arrive.</p><h2>Compatibility and license</h2><p>Extract the ZIP before opening files. PDFs require a PDF viewer. HTML tools require a current browser; support for local HTML files varies on phones. Nora’s workbook is .xlsx and requires a compatible spreadsheet application. One purchaser may use, edit and print the files for personal or internal household/business use. Redistribution, resale, sublicensing and public uploads are prohibited.</p><h2>Immediate delivery and refunds</h2><p>You request immediate access to the files when completing checkout. Free orders have no payment to refund. For any earlier paid order, the original 14-day refund policy remains: email hello@web-by-elie.com within 14 days with the purchase email and receipt reference if the product is not a fit. Mandatory consumer rights remain unaffected.</p><h2>Product scope</h2><p>The kits provide general planning, communication examples and arithmetic tools. They do not promise health, financial or relationship outcomes. Built-in cost examples are hypothetical. The presenters are fictional AI characters and are not represented as qualified practitioners or as having real lived experience.</p><h2>Support</h2><p>Email hello@web-by-elie.com for help, corrections, download recovery or refund requests. Never send passwords or card details.</p>'''),
 'data-deletion':('Data Deletion Instructions','''<h2>Request deletion</h2><p>Email hello@web-by-elie.com with the subject “Creator shop data request.” Include the purchase email and receipt reference so we can identify the relevant record. Never include card details or passwords.</p><h2>What the shops hold</h2><p>The shop has no customer login or password. Stripe may create a customer record for a free order; this does not create a subscription or future charge. Cloudflare stores limited delivery records with the purchased product, Stripe session reference, payment status and access expiry for 30 days. Resend processes delivery emails. Stripe holds payment and financial records under its own policies and legal obligations.</p><h2>Letters</h2><p>Use the unsubscribe link in a letter or email hello@web-by-elie.com to stop letters or request removal of your subscription data. Minimal suppression information may be retained to honor your choice.</p><h2>What deletion changes</h2><p>Removing a delivery record may affect download recovery. Some payment or support information may need to remain for legal, accounting, fraud or dispute purposes. We will explain any applicable limits rather than promise that all third-party records are removed.</p><h2>Data on your device</h2><p>Offline planner notes, exported backups and downloaded files stay on your device. Clear the planner’s browser storage or delete files yourself. Website display preferences use the local storage key tilbury-display; the delivery reference uses session storage. Deleting these does not delete Stripe payment records.</p><h2>Platform-controlled data</h2><p>Manage Instagram, Stripe and other platform data through their own privacy tools. We can address information held by Web By Elie and coordinate relevant processor requests where applicable.</p>'''),
}
for slug,(title,copy) in policies.items():
    path='creators.'+slug
    body=f'<body><header class="wrap bar"><a class="brand" href="june.rowan">Creator shops</a>{settings()}</header><main class="wrap policy"><p class="eyebrow">Web By Elie · October 16, 2026</p><h1>{title}</h1>{copy}<p><a href="june.rowan">June</a> · <a href="nora.vela">Nora</a> · <a href="elena.brooks">Elena</a></p></main>{footer("Creator shops")}{dialog()}</body></html>'
    (ROOT/(path+'.html')).write_text(head(title+' | Creator shops',title+' for Web By Elie digital products.',path)+body)

order=head('Your digital download | Web By Elie','Access your purchased digital product.','creators.order').replace('</head>',f'<meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><link rel="stylesheet" href="assets/creator-shop.css?v={V}"></head>')
order+=f'<body><header class="wrap bar"><a class="brand" href="june.rowan">Web By Elie · Digital products</a>{settings()}</header><main class="wrap policy"><p class="eyebrow">Your digital kit</p><h1 id="order-title">Getting your download.</h1><p id="order-status" role="status">Checking your order…</p><div id="order-result" hidden><a class="button" id="download">Download your ZIP</a><p id="expiry"></p><p>Extract the ZIP, open START-HERE.txt, and keep the files for continued use. Your private link grants access to this purchase; do not share it.</p></div><button class="button" id="retry" hidden>Check again</button><p>Need help? Email <a href="mailto:hello@web-by-elie.com">hello@web-by-elie.com</a> with your purchase email and receipt reference. Never send card details.</p></main>{footer("Creator shops")}{dialog()}<script src="assets/creator-order.js?v={V}" defer></script></body></html>'
(ROOT/'creators.order.html').write_text(order)
print('Generated three shops, purchase policies and private delivery page.')
